memory-ts-quickstart:
import { MemoryManager } from 'actrone-memory'

// In-memory + local embedder by default: no Redis/Qdrant required to start
const memory = await MemoryManager.create()

await memory.storeTurn(
  'research-agent',
  'session-42',
  'Summarise Q4 earnings for AAPL',
  'Apple reported revenue of $119.6B in Q4 2024, up 6% YoY...',
)

const context = await memory.retrieveContext(
  'research-agent',
  'session-42',
  'Apple revenue Q4',
  2000,
)

// context.recentTurns          : recent session turns (L1)
// context.episodicMemories     : semantically relevant long-term memories (L2)
// context.totalTokensUsed      : tokens consumed across both tiers
// context.retrievalDurationMs  : retrieval latency in milliseconds

memory-ts-use-case-assistant:
import { MemoryManager, type Sensitivity } from "actrone-memory";

// One scope per user: everything below is recalled for this user only.
const scopeFor = (userId: string) => `user:${userId}`;

// Keep something the user told you, with the sensitivity you judge it to have.
export async function rememberAboutUser(
  memory: MemoryManager,
  userId: string,
  fact: string,
  sensitivity: Sensitivity = "low",
) {
  return memory.injectMemory(scopeFor(userId), fact, 0.9, "profile", [], "user", sensitivity);
}

// Each conversation is a session: its turns feed the next reply in the same conversation.
export async function recordTurn(
  memory: MemoryManager,
  userId: string,
  conversationId: string,
  userMessage: string,
  reply: string,
) {
  await memory.storeTurn(scopeFor(userId), conversationId, userMessage, reply);
}

// Recall for a new message; each fact keeps its tag, so you decide what the model sees.
export async function recallFor(
  memory: MemoryManager,
  userId: string,
  conversationId: string,
  message: string,
) {
  const context = await memory.retrieveContext(scopeFor(userId), conversationId, message, 1500);
  return {
    facts: context.episodicMemories.map((m) => ({ content: m.content, sensitivity: m.sensitivity })),
    recentTurns: context.recentTurns.length,
  };
}

// Closing a conversation drops its turns. What you remembered about the user stays.
export async function endConversation(memory: MemoryManager, userId: string, conversationId: string) {
  await memory.clearSession(scopeFor(userId), conversationId);
}

memory-ts-use-case-coding:
import { MemoryManager } from "actrone-memory";

// One scope per repository, so one codebase's conventions never leak into another's.
const scopeFor = (repo: string) => `repo:${repo}`;

// Record a convention once, when the developer or a code review states it.
export async function learnConvention(memory: MemoryManager, repo: string, convention: string) {
  return memory.injectMemory(scopeFor(repo), convention, 0.9, "conventions", ["convention"], "user");
}

// Before each request, recall this task's conventions within a token budget.
export async function conventionsFor(
  memory: MemoryManager,
  repo: string,
  sessionId: string,
  task: string,
) {
  const context = await memory.retrieveContext(scopeFor(repo), sessionId, task, 800);
  return {
    conventions: context.episodicMemories.map((m) => m.content),
    tokensUsed: context.totalTokensUsed,
  };
}

// Keep the exchange, so the next request in this session sees it.
export async function recordExchange(
  memory: MemoryManager,
  repo: string,
  sessionId: string,
  request: string,
  answer: string,
) {
  await memory.storeTurn(scopeFor(repo), sessionId, request, answer);
}

memory-ts-use-case-support:
import { MemoryManager } from "actrone-memory";

// Long-term memory is scoped by its first argument, so one scope per customer keeps them apart.
const scopeFor = (customerId: string) => `customer:${customerId}`;

// Seed what your CRM already knows, tagged with its source and how sensitive it is.
export async function importAccount(memory: MemoryManager, customerId: string): Promise<void> {
  const scope = scopeFor(customerId);
  // Arguments: scope, fact, importance, session label, topic tags, source, sensitivity.
  await memory.injectMemory(scope, "The customer is on the Business plan and renews in March.",
    0.9, "crm", ["plan"], "import:crm", "none");
  await memory.injectMemory(scope, "The customer billing email is dana@example.com.",
    0.6, "crm", ["contact"], "import:crm", "pii");
}

// Answer a ticket with what you know about this customer, minus personal data.
export async function answerTicket(
  memory: MemoryManager,
  customerId: string,
  ticketId: string,
  question: string,
  callModel: (question: string, facts: string[]) => Promise<string>,
): Promise<string> {
  const scope = scopeFor(customerId);
  const context = await memory.retrieveContext(scope, ticketId, question, 2000);
  const facts = context.episodicMemories
    .filter((m) => m.sensitivity === "none" || m.sensitivity === "low")
    .map((m) => m.content);
  const reply = await callModel(question, facts);
  await memory.storeTurn(scope, ticketId, question, reply);
  return reply;
}

// A deletion request: erase the customer's memories and this ticket's turns.
export async function forgetCustomer(memory: MemoryManager, customerId: string, ticketId: string) {
  await memory.eraseAgentMemories(scopeFor(customerId), ticketId);
}
